syntax:
Returning objects by value, letting the compiler handle RVO/NRVO:

```c++
MyClass func() {
  MyClass obj; // Object construction
  // ... some operations on obj
  return obj; // Compiler might perform RVO/NRVO here
}
```

code_example:
#include <iostream>
#include <string>
class MyClass {
public:
  std::string data;
  MyClass(const std::string& d) : data(d) { std::cout << "MyClass constructor called\n"; }
  MyClass(const MyClass& other) : data(other.data) { std::cout << "MyClass copy constructor called\n"; }
  ~MyClass() { std::cout << "MyClass destructor called\n"; }
};
MyClass createObject() {
  MyClass obj("Hello");
  return obj;
}
int main() {
  MyClass myObj = createObject();
  std::cout << myObj.data << "\n";
  return 0;
}
